		t.Error("expected stale state on sync failure with cached data")
	}
	if detail.SourceState.ErrorCode == "" {
		t.Error("expected error code in stale source state")
	}
}

func TestSyncWorkspace_FailureWithNoCachedData(t *testing.T) {
	db := &fakeDB{}
