// Package integration contains end-to-end integration tests that exercise the full
// HTTP server stack: routing → handler → service → database interface.
//
// All tests use the FakeDB and FakeAdapter from testhelpers rather than a live
// PostgreSQL database — no Docker or external services are required.
// The scenarios map directly to the T5 task spec deliverables.
package integration_test

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/gin-gonic/gin"

	"github.com/tiendv89/workflow-backend/internal/domain"
	"github.com/tiendv89/workflow-backend/internal/handler"
	"github.com/tiendv89/workflow-backend/internal/service"
	"github.com/tiendv89/workflow-backend/internal/testhelpers"
)

const (
	wsID       = "11111111-1111-1111-1111-111111111111"
	featureID  = "workspace-data-backend"
	taskID     = "T1"
	repoURL    = "https://github.com/testorg/test-repo"
)

// newServer creates a fully wired gin test server identical to the production
// server except that the database and adapter calls go to fake implementations.
func newServer(db service.DatabaseReader, adp service.AdapterCaller) *httptest.Server {
	gin.SetMode(gin.TestMode)
	svc := service.New(db, adp, 30*time.Minute)
	h := handler.New(svc)
	r := gin.New()
	r.Use(gin.Recovery())
	api := r.Group("/api")
	h.RegisterRoutes(api)
	return httptest.NewServer(r)
}

// do performs an HTTP request against the test server and returns the response.
func do(t *testing.T, srv *httptest.Server, method, path, body string) *http.Response {
	t.Helper()
	var reqBody *strings.Reader
	if body != "" {
		reqBody = strings.NewReader(body)
	} else {
		reqBody = strings.NewReader("")
	}
	req, err := http.NewRequest(method, srv.URL+path, reqBody)
	if err != nil {
		t.Fatalf("build request %s %s: %v", method, path, err)
	}
	if body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("execute request %s %s: %v", method, path, err)
	}
	return resp
}

func decode[T any](t *testing.T, resp *http.Response) T {
	t.Helper()
	defer resp.Body.Close()
	var out T
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	return out
}

// --- T5 scenario 1: first import — GitHub fixture → DB write → read API ---

func TestImport_FirstImport_201(t *testing.T) {
	ws := testhelpers.NewWorkspace(wsID, "My Workspace", "my-workspace")
	src := testhelpers.NewGitHubSource(wsID, repoURL)
	db := &testhelpers.FakeDB{
		Workspaces: []testhelpers.FakeDB_WorkspaceSlice{{ws}}.workspaces(),
		GitHubSrcs: map[string]interface{}{wsID: src},
	}
	db2 := buildFakeDB(ws, nil, nil, nil, nil, nil, map[string]interface{}{wsID: src})
	adp := &testhelpers.FakeAdapter{ImportedWorkspaceID: wsID}
	srv := newServer(db2, adp)
	defer srv.Close()

	resp := do(t, srv, http.MethodPost, "/api/workspaces/import",
		`{"repo_url":"https://github.com/testorg/test-repo","name":"My Workspace"}`)
	if resp.StatusCode != http.StatusCreated {
		t.Fatalf("expected 201, got %d", resp.StatusCode)
	}

	var detail domain.WorkspaceDetail
	if err := json.NewDecoder(resp.Body).Decode(&detail); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	resp.Body.Close()

	if detail.ID != wsID {
		t.Errorf("expected workspace ID %s, got %s", wsID, detail.ID)
	}
	if detail.Name != "My Workspace" {
		t.Errorf("expected name 'My Workspace', got %q", detail.Name)
	}
	if detail.RepoURL != repoURL {
		t.Errorf("expected repo URL %s, got %s", repoURL, detail.RepoURL)
	}
}

