	defer srv.Close()

	resp := do(t, srv, http.MethodPost, "/api/workspaces/import", `{}`)
	if resp.StatusCode != http.StatusBadRequest {
		t.Errorf("expected 400 for missing repo_url, got %d", resp.StatusCode)
	}
	resp.Body.Close()
}

func TestImport_AdapterFailure_500(t *testing.T) {
	db := buildFakeDB(testhelpers.NewWorkspace(wsID, "W", "w"), nil, nil, nil, nil, nil, nil)
	adpErr := domain.NewAdapterError(domain.ErrAdapterInternal, "rpc unavailable")
	srv := newServer(db, &testhelpers.FakeAdapter{ImportErr: adpErr})
	defer srv.Close()

	resp := do(t, srv, http.MethodPost, "/api/workspaces/import",
		`{"repo_url":"https://github.com/org/repo"}`)
	if resp.StatusCode != http.StatusInternalServerError {
		t.Errorf("expected 500 for adapter error, got %d", resp.StatusCode)
	}
	var apiErr domain.APIError
	json.NewDecoder(resp.Body).Decode(&apiErr)
	resp.Body.Close()
	if apiErr.Code != domain.ErrAdapterInternal {
		t.Errorf("expected ErrAdapterInternal, got %s", apiErr.Code)
	}
