	ws := testhelpers.NewWorkspace(wsID, "W", "w")
	db := buildFakeDB(ws, nil, nil, nil, nil, nil, nil) // no sync run
	srv := newServer(db, &testhelpers.FakeAdapter{})
	defer srv.Close()

	resp := do(t, srv, http.MethodGet, "/api/workspaces/"+wsID, "")
	var detail domain.WorkspaceDetail
	json.NewDecoder(resp.Body).Decode(&detail)
	resp.Body.Close()

	if !detail.SourceState.Stale {
		t.Error("expected stale=true when workspace has never been synced")
	}
}

func TestSourceState_NotStale_AfterSuccessfulRecentSync(t *testing.T) {
	ws := testhelpers.NewWorkspace(wsID, "W", "w")
	// Sync run with finished_at = now (well within stale threshold of 30 min).
	sr := testhelpers.NewSyncRun(wsID, "import", "full_reconciliation", "success")
	// Set finished_at to now.
	_ = sr.FinishedAt.Scan(time.Now().UTC())

	db := buildFakeDB(ws, []interface{}{sr}, nil, nil, nil, nil, nil)
	srv := newServer(db, &testhelpers.FakeAdapter{})
	defer srv.Close()

	resp := do(t, srv, http.MethodGet, "/api/workspaces/"+wsID, "")
	var detail domain.WorkspaceDetail
	json.NewDecoder(resp.Body).Decode(&detail)
	resp.Body.Close()

	if detail.SourceState.Stale {
		t.Error("expected stale=false after a recent successful sync")
	}
}

func TestSourceState_Stale_AfterFailedSync(t *testing.T) {
	ws := testhelpers.NewWorkspace(wsID, "W", "w")
	failedRun := testhelpers.NewSyncRun(wsID, "manual", "full_reconciliation", "failed")
	errCode := "GITHUB_RATE_LIMIT"
	errMsg := "rate limit reached"
	failedRun.ErrorCode = &errCode
	failedRun.ErrorMessage = &errMsg

	db := buildFakeDB(ws, []interface{}{failedRun}, nil, nil, nil, nil, nil)
	srv := newServer(db, &testhelpers.FakeAdapter{})
	defer srv.Close()

	resp := do(t, srv, http.MethodGet, "/api/workspaces/"+wsID, "")
	var detail domain.WorkspaceDetail
	json.NewDecoder(resp.Body).Decode(&detail)
	resp.Body.Close()

	if !detail.SourceState.Stale {
		t.Error("expected stale=true when latest sync run failed")
	}
	if detail.SourceState.ErrorCode != errCode {
		t.Errorf("expected error_code %q, got %q", errCode, detail.SourceState.ErrorCode)
	}
}

// --- helpers ---

// FakeDB_WorkspaceSlice is a helper to convert a []interface{} to []database.Workspace.
// We use a typed helper to avoid re-declaring the concrete fake db.
type FakeDB_WorkspaceSlice struct {
	ws interface{}
}

func (s FakeDB_WorkspaceSlice) workspaces() interface{} { return s.ws }

// buildFakeDB constructs a testhelpers.FakeDB from typed interface{} slices,
// unwrapping the concrete database types as needed.
func buildFakeDB(
	ws interface{},
	syncRuns []interface{},
	features []interface{},
	documents []interface{},
	tasks []interface{},
	activity []interface{},
	githubSrcs map[string]interface{},
) service.DatabaseReader {
	return buildFakeDBMulti(toSlice1(ws), syncRuns, features, documents, tasks, activity, githubSrcs)
}

func buildFakeDBMulti(
	workspaces []interface{},
	syncRuns []interface{},
	features []interface{},
	documents []interface{},
	tasks []interface{},
	activity []interface{},
	githubSrcs map[string]interface{},
) service.DatabaseReader {
	f := &testhelpers.FakeDB{}
	for _, w := range workspaces {
		if v, ok := w.(testhelpers.WorkspaceType); ok {
			f.AddWorkspace(v)
		}
	}
	for _, sr := range syncRuns {
		if v, ok := sr.(testhelpers.SyncRunType); ok {
			f.AddSyncRun(v)
		}
	}
	for _, feat := range features {
		if v, ok := feat.(testhelpers.FeatureType); ok {
			f.AddFeature(v)
		}
	}
	for _, doc := range documents {
		if v, ok := doc.(testhelpers.DocumentType); ok {
			f.AddDocument(v)
		}
	}
	for _, t := range tasks {
		if v, ok := t.(testhelpers.TaskType); ok {
			f.AddTask(v)
		}
	}
	for _, a := range activity {
		if v, ok := a.(testhelpers.ActivityType); ok {
			f.AddActivity(v)
		}
	}
	if githubSrcs != nil {
		if f.GitHubSrcs == nil {
			f.GitHubSrcs = make(map[string]testhelpers.GitHubSourceType)
		}
		for k, v := range githubSrcs {
			if src, ok := v.(testhelpers.GitHubSourceType); ok {
				f.GitHubSrcs[k] = src
			}
		}
	}
	return f
}

func buildFakeDB_empty() service.DatabaseReader {
	return &testhelpers.FakeDB{}
}

func toSlice1(v interface{}) []interface{} {
	if v == nil {
		return nil
	}
	return []interface{}{v}
}

