// --- T5 scenario 5: workspace list route ---

func TestListWorkspaces_ReturnsWorkspacesWithSourceState(t *testing.T) {
	ws1 := testhelpers.NewWorkspace(wsID, "Workspace One", "workspace-one")
	ws2ID := "22222222-2222-2222-2222-222222222222"
	ws2 := testhelpers.NewWorkspace(ws2ID, "Workspace Two", "workspace-two")
	successRun := testhelpers.NewSyncRun(wsID, "import", "full_reconciliation", "success")
	src := testhelpers.NewGitHubSource(wsID, repoURL)

	db := &testhelpers.FakeDB{
		Workspaces: []interface{}{ws1, ws2},
		SyncRuns:   []interface{}{successRun},
		GitHubSrcs: map[string]interface{}{wsID: src},
	}
	fdb := buildFakeDBMulti([]interface{}{ws1, ws2}, []interface{}{successRun}, nil, nil, nil, nil,
		map[string]interface{}{wsID: src})
	_ = db
	srv := newServer(fdb, &testhelpers.FakeAdapter{})
	defer srv.Close()

	resp := do(t, srv, http.MethodGet, "/api/workspaces", "")
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("expected 200, got %d", resp.StatusCode)
	}

	var workspaces []domain.WorkspaceSummary
	json.NewDecoder(resp.Body).Decode(&workspaces)
	resp.Body.Close()

	if len(workspaces) != 2 {
		t.Errorf("expected 2 workspaces, got %d", len(workspaces))
	}

	// Verify source state is populated.
	var ws1Result *domain.WorkspaceSummary
	for i := range workspaces {
		if workspaces[i].ID == wsID {
			ws1Result = &workspaces[i]
		}
	}
	if ws1Result == nil {
		t.Fatalf("workspace %s not found in response", wsID)
	}
	if ws1Result.RepoURL != repoURL {
		t.Errorf("expected repo_url %s, got %s", repoURL, ws1Result.RepoURL)
	}
