// --- T5 scenario 5: feature detail route ---

func TestGetFeature_Detail_IncludesDocumentsTasksActivity(t *testing.T) {
	ws := testhelpers.NewWorkspace(wsID, "W", "w")
	feat := testhelpers.NewFeature(wsID, featureID, "Workspace Data Backend", "in_implementation", "in_implementation")
	doc := testhelpers.NewDocument(wsID, featureID, "product_spec",
		"docs/features/workspace-data-backend/product-spec.md",
		"https://github.com/testorg/test-repo/blob/main/docs/features/workspace-data-backend/product-spec.md")
	task := testhelpers.NewTask(wsID, featureID, taskID, "Go backend foundation", "done", []string{})
	event := testhelpers.NewActivityEvent(wsID, featureID, taskID, "done", "agent@example.com", "Task completed", 0)

	db := buildFakeDB(ws, nil,
		[]interface{}{feat},
		[]interface{}{doc},
		[]interface{}{task},
		[]interface{}{event},
		nil)
	srv := newServer(db, &testhelpers.FakeAdapter{})
	defer srv.Close()

	resp := do(t, srv, http.MethodGet, "/api/workspaces/"+wsID+"/features/"+featureID, "")
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("expected 200, got %d", resp.StatusCode)
	}

	var detail domain.FeatureDetail
	json.NewDecoder(resp.Body).Decode(&detail)
	resp.Body.Close()

	if detail.FeatureID != featureID {
		t.Errorf("expected feature_id %s, got %s", featureID, detail.FeatureID)
	}
	if detail.WorkspaceID != wsID {
		t.Errorf("expected workspace_id %s, got %s", wsID, detail.WorkspaceID)
	}
	if len(detail.Documents) != 1 {
		t.Errorf("expected 1 document, got %d", len(detail.Documents))
	}
	if detail.Documents[0].DocumentType != "product_spec" {
		t.Errorf("expected document_type 'product_spec', got %q", detail.Documents[0].DocumentType)
